export async function chooseDuplicate(title){
 let data;try{const response=await fetch('/api/scores',{signal:AbortSignal.timeout(6000)});if(!response.ok)return null;data=await response.json();}catch{return null;}const key=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[\s《》「」_-]/g,'');const matches=(data.scores||[]).filter(s=>s.ready&&key(s.title)===key(title));if(!matches.length)return null;
 const existing=matches.sort((a,b)=>(b.saved||0)-(a.saved||0))[0];
 return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='duplicate-score-dialog';const heading=document.createElement('h2');heading.textContent='已存在同名曲谱';const description=document.createElement('p');description.textContent=`《${title}》已在云曲库中，请选择要使用的版本。`;const old=document.createElement('button');old.textContent='使用云端已有版本';const fresh=document.createElement('button');fresh.textContent='使用本次导入版本';const finish=value=>{dialog.close();dialog.remove();resolve(value);};old.onclick=()=>finish(existing);fresh.onclick=()=>finish(null);dialog.addEventListener('cancel',e=>{e.preventDefault();finish(existing);});dialog.append(heading,description,old,fresh);document.body.append(dialog);dialog.showModal();});
}
